challenge_result.network_analysis:
{
  "summary": "The mongo container has exited (L10), breaking the UDR backend and starving the PCF; P-CSCF, I-CSCF, S-CSCF, and SMF are demoted as downstream reporters of the resulting N5 QoS authorization failures (L09), while UPF is demoted because its N3 GTP flags are known over-flagged drops in the idle bucket (L03).",
  "layer_status": {
    "infrastructure": {
      "rating": "green",
      "evidence": [
        "Network topology shows Docker network is active",
        "Links are active except those pointing to the exited Mongo container"
      ],
      "note": "Infrastructure layer is healthy."
    },
    "ran": {
      "rating": "green",
      "evidence": [
        "No RAN metrics flagged",
        "AMF ran_ue count is stable"
      ],
      "note": "RAN components are operating normally."
    },
    "core": {
      "rating": "red",
      "evidence": [
        "MongoDB container is exited",
        "UDR, PCF, NSSF, and BSF links to MongoDB are inactive",
        "SMF bearers_per_ue metric shifted"
      ],
      "note": "Core data layer is broken due to MongoDB failure, breaking subscriber data retrieval via UDR."
    },
    "ims": {
      "rating": "yellow",
      "evidence": [
        "derived.pcscf_sip_error_ratio spiked to 0.17",
        "CSCF cdp_replies_per_ue and rcv_requests_register_per_ue shifted"
      ],
      "note": "IMS components are running but P-CSCF is rejecting SIP requests due to upstream core network N5 authorization failures."
    }
  },
  "hypotheses": [
    {
      "id": "h1",
      "statement": "mongo is the source of the derived.pcscf_sip_error_ratio spike and the subsequent call setup and registration failures. The mongo container is exited, breaking the UDR backend and triggering the pcscf_n5_registration and pcscf_n5_call_setup branches where PCF returns non-201, forcing P-CSCF to reject SIP requests.",
      "primary_suspect_nf": "mongo",
      "supporting_events": [],
      "explanatory_fit": 0.95,
      "falsification_probes": [
        "Inspect MongoDB container logs to determine the cause of the exit.",
        "Check UDR logs to verify database connection refusal.",
        "Check PCF logs to verify it is failing to fetch subscriber policy and returning non-201 to P-CSCF on N5 POST."
      ],
      "specificity": "specific"
    }
  ]
}

